function t(locale, key, params) {
  const lang = I18N[locale] ? locale : 'el';
  const entry = I18N[lang][key] ?? I18N.el[key];
  if (entry === undefined) return key;
  return typeof entry === 'function' ? entry(params || {}) : entry;
}

window.I18N = I18N;
// Exposed under a distinct name (not `window.t`) because app.js — a classic,
// non-module script sharing this same global scope — declares its own
// top-level `function t(...)`, which would otherwise silently overwrite
// this one and turn every translation lookup into infinite self-recursion.
window.i18nTranslate = t;
